  {
   "id": "M1:T5",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The priority scheme for calls described in section 10.2 is also valid for data applications. Automatic fax",
