   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Where fax functionality is provided, it shall be possible to interrupt the fax to make or receive a high priority voice or data call. Train control applications",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T8",
   "speaker": "Analyst",
